recipes.code:
{
  "inputs": [
    {
      "id": "soma-api-key",
      "type": "promptString",
      "description": "Optional bearer token or upstream API key for provider-backed calls that use SomaClient. Keep secret.",
      "password": true
    }
  ],
  "servers": {
    "soma": {
      "type": "stdio",
      "command": "docker",
      "args": [
        "run",
        "-i",
        "--rm",
        "ghcr.io/dinglebear-ai/soma:0.7.0",
        "mcp"
      ],
      "env": {
        "SOMA_HOME": "/data",
        "SOMA_PROVIDER_DIR": "/data/providers",
        "SOMA_API_URL": "<soma-api-url>",
        "SOMA_API_KEY": "${input:soma-api-key}",
        "RUST_LOG": "info"
      }
    }
  }
}
